/**
 * MODO DEMOSTRACIÓN — fotos REALES de las cajas, tal como las publica CIMA (AEMPS) para cada número de registro
 * (/cima/fotos/full/materialas/{nregistro}/{nregistro}_materialas.jpg), reducidas a 400-440 px de ancho.
 * La app real las muestra desde la URL oficial que devuelve el backend (fotoUrl); en la vista previa web la
 * política de seguridad no permite cargar imágenes externas, así que se incluyen aquí. Descargadas el 09/10/2026.
 */
export const DEMO_BOX_PHOTOS: Readonly<Record<string, string>> = {
  '70310':
    'data:image/jpeg;base64,',
  '69478':
    'data:image/jpeg;base64,',
  '68331':
    'data:image/jpeg;base64,',
  '70039':
    'data:image/jpeg;base64,',
  '63710':
    'data:image/jpeg;base64,',
  '71269':
    'data:image/jpeg;base64,',
};

/** Foto real de la caja de ese medicamento de ejemplo, o null si CIMA no publica ninguna. */
export function demoBoxPhoto(id: string): string | null {
  return DEMO_BOX_PHOTOS[id] ?? null;
}
